/**
 * @suppress
 */
public object FfiConverterTypePlasmaWaveCore: FfiConverter<PlasmaWaveCore, Pointer> {

    override fun lower(value: PlasmaWaveCore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): PlasmaWaveCore {
        return PlasmaWaveCore(value)
    }

    override fun read(buf: ByteBuffer): PlasmaWaveCore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: PlasmaWaveCore) = 8UL

    override fun write(value: PlasmaWaveCore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



